package com.example.medilembrete;
import android.app.Activity; import android.os.Bundle; import android.widget.TextView; import android.widget.Button; import android.content.DialogInterface; import androidx.appcompat.app.AlertDialog;
import com.example.medilembrete.data.AppDatabase; import com.example.medilembrete.data.entity.Medicamento; import com.example.medilembrete.data.entity.Horario; import java.text.SimpleDateFormat; import java.util.List; import java.util.Locale;
public class DetalheMedicamentoActivity extends Activity {
 private AppDatabase db; private long id;
 @Override protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_detalhe_medicamento); id=getIntent().getLongExtra("medicamento_id",-1); db=AppDatabase.getInstance(this);
 findViewById(R.id.btnVoltarDetalhe).setOnClickListener(v->finish());
 db.medicamentoDao().buscarPorId(id).observe(this,m->{if(m!=null) preencher(m);});
 db.horarioDao().listarPorMedicamento(id).observe(this,hs->{StringBuilder s=new StringBuilder("Horários: "); if(hs!=null)for(int i=0;i<hs.size();i++){if(i>0)s.append("  ·  ");s.append(hs.get(i).getHorario());} ((TextView)findViewById(R.id.txtHorariosDetalhe)).setText(s.toString());});
 findViewById(R.id.btnExcluirDetalhe).setOnClickListener(v->new AlertDialog.Builder(this).setTitle("Excluir medicamento?").setMessage("Essa ação não poderá ser desfeita.").setNegativeButton("Cancelar",null).setPositiveButton("Excluir",(d,w)->AppDatabase.executor.execute(()->{Medicamento m=db.medicamentoDao().buscarPorId(id).getValue(); if(m!=null)db.medicamentoDao().excluir(m); runOnUiThread(this::finish);})).show());
 }
 private void preencher(Medicamento m){((TextView)findViewById(R.id.txtNomeDetalhe)).setText(m.getNome());((TextView)findViewById(R.id.txtDosagemDetalhe)).setText(m.getDosagem());((TextView)findViewById(R.id.txtFormaDetalhe)).setText("Forma: "+m.getForma()+"  ·  "+m.getQuantidadePorDose()+" por dose");((TextView)findViewById(R.id.txtFrequenciaDetalhe)).setText("Frequência: "+(m.getIntervaloHoras()==24?"1 vez ao dia":m.getIntervaloHoras()+" em "+m.getIntervaloHoras()+" horas"));((TextView)findViewById(R.id.txtDuracaoDetalhe)).setText("Duração: "+(m.getDataFim()==null?"Contínuo":new SimpleDateFormat("dd/MM/yyyy",Locale.getDefault()).format(m.getDataFim())));((TextView)findViewById(R.id.txtObservacoesDetalhe)).setText(m.getObservacoes()==null||m.getObservacoes().isEmpty()?"Sem observações":"Observações: "+m.getObservacoes());}
}